<script setup lang="ts">
import { computed, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { unifiedFactories, unifiedRepository, type Asset, type Insight, type Resource, type Seed } from '@/domain/unified'
import { assetRepository, hashOpenBytes } from '@/core/content/assets'
import { listRealityDocuments } from '@/domain/reality'

const tick = ref(0); const title = ref(''); const body = ref(''); const kind = ref<'resource' | 'seed'>('resource'); const resourceUri = ref(''); const resourceExpiresAt = ref(''); const resourceAssetIds = ref<string[]>([])
const assetPath = ref(''); const assetMimeType = ref(''); const assetSize = ref('0'); const assetHash = ref(''); const assetVersion = ref('1'); const assetExternalUri = ref('')
const resources = computed(() => { void tick.value; const ids = new Set(listRealityDocuments({ types: ['resource'] }).map(item => item.id)); return unifiedRepository.list<Resource>('resource').filter(item => ids.has(item.calmyId) && item.status !== 'retired') })
const insights = computed(() => { void tick.value; const ids = new Set(listRealityDocuments({ types: ['insight'] }).map(item => item.id)); return unifiedRepository.list<Insight>('insight').filter(item => ids.has(item.calmyId) && item.status !== 'retired') })
const seeds = computed(() => { void tick.value; const ids = new Set(listRealityDocuments({ types: ['seed'] }).map(item => item.id)); return unifiedRepository.list<Seed>('seed').filter(item => ids.has(item.calmyId) && item.status !== 'retired') })
const assets = computed(() => { void tick.value; const ids = new Set(listRealityDocuments({ types: ['asset'] }).map(item => item.id)); return unifiedRepository.list<Asset>('asset').filter(item => ids.has(item.calmyId)).sort((a, b) => b.updatedAt - a.updatedAt) })
function addItem() {
  if (!title.value.trim() || !body.value.trim()) { ElMessage.warning('标题和内容都需要保留'); return }
  if (kind.value === 'resource') unifiedRepository.create(unifiedFactories.resource({ title: title.value.trim(), kind: 'knowledge', status: 'active', body: body.value.trim(), uri: resourceUri.value.trim() || undefined, expiresAt: resourceExpiresAt.value ? Date.parse(resourceExpiresAt.value) : undefined, assetIds: [...resourceAssetIds.value], matterIds: [], sourceIds: [], tags: [] }))
  else unifiedRepository.create(unifiedFactories.seed({ title: title.value.trim(), body: body.value.trim(), status: 'open', sourceRecordIds: [], targetMatterIds: [], tags: [] }))
  title.value = ''; body.value = ''; resourceUri.value = ''; resourceExpiresAt.value = ''; resourceAssetIds.value = []; tick.value++; ElMessage.success(kind.value === 'resource' ? '资源已加入 Library' : 'Seed 已保留')
}
function updateResourceStatus(item: Resource, status: Resource['status']) { try { unifiedRepository.updateResourceStatus(item.calmyId, status, { expectedRevision: item.revision }); tick.value++ } catch (error) { ElMessage.error(error instanceof Error ? error.message : '资源状态更新失败') } }
function updateResourceAssets(item: Resource, event: Event): void { try { unifiedRepository.update<Resource>('resource', item.calmyId, { assetIds: selectedIds(event) }, { expectedRevision: item.revision }); tick.value++ } catch (error) { ElMessage.error(error instanceof Error ? error.message : '资源附件关联更新失败') } }
function retireSeed(item: Seed) { unifiedRepository.update<Seed>('seed', item.calmyId, { status: 'retired', archivedAt: Date.now() }, { expectedRevision: item.revision }); tick.value++ }
function addAsset() {
  const sizeBytes = Number(assetSize.value); const version = Number(assetVersion.value)
  if (!assetPath.value.trim() || !assetMimeType.value.trim() || !assetHash.value.trim() || !Number.isFinite(sizeBytes) || sizeBytes < 0 || !Number.isInteger(version) || version < 1) { ElMessage.warning('Asset 需要路径、类型、hash、非负大小和正整数版本'); return }
  try { unifiedRepository.createAsset({ path: assetPath.value.trim(), mimeType: assetMimeType.value.trim(), sizeBytes, hash: assetHash.value.trim(), lifecycle: 'active', version, externalUri: assetExternalUri.value.trim() || undefined }); assetPath.value = ''; assetMimeType.value = ''; assetSize.value = '0'; assetHash.value = ''; assetVersion.value = '1'; assetExternalUri.value = ''; tick.value++; ElMessage.success('Asset 元数据已保存') }
  catch (error) { ElMessage.error(error instanceof Error ? error.message : 'Asset 保存失败') }
}
function updateAssetLifecycle(item: Asset, lifecycle: Asset['lifecycle']) { try { unifiedRepository.updateAssetLifecycle(item.calmyId, lifecycle, { expectedRevision: item.revision }); tick.value++ } catch (error) { ElMessage.error(error instanceof Error ? error.message : 'Asset 生命周期更新失败') } }
function resourceStatusLabel(status: Resource['status']): string { return ({ active: '有效', expired: '已过期', retired: '已退休' })[status] }
function assetLifecycleLabel(lifecycle: Asset['lifecycle']): string { return ({ active: '存在', expired: '过期', retired: '退休', missing: '缺失' })[lifecycle] }
function assetLifecycleValue(event: Event): Asset['lifecycle'] { const value = (event.target as HTMLInputElement).value; return value === 'expired' || value === 'retired' || value === 'missing' ? value : 'active' }
function selectedIds(event: Event): string[] { return Array.from((event.target as HTMLSelectElement).selectedOptions).map(option => option.value) }
function resourceAssetState(item: Resource): string { const linked = item.assetIds.map(id => assets.value.find(asset => asset.calmyId === id)); const missing = linked.filter(asset => !asset || asset.lifecycle === 'missing').length; const retired = linked.filter(asset => asset?.lifecycle === 'retired').length; return missing ? `${missing} 个附件缺失` : retired ? `${retired} 个附件已退休` : `${linked.length} 个附件可用` }
function normalizedAssetPath(name: string): string { const safeName = name.replace(/\\/g, '/').split('/').pop()?.replace(/\.\.+/g, '_').trim() || 'unnamed-asset'; return `assets/${safeName}` }
async function importBinaryAsset(event: Event): Promise<void> {
  const input = event.target as HTMLInputElement
  const file = input.files?.[0]
  if (!file) return
  try {
    const data = new Uint8Array(await file.arrayBuffer())
    const path = normalizedAssetPath(file.name)
    const openAsset = { path, data, mimeType: file.type || 'application/octet-stream' }
    const outcome = assetRepository.importAsset(openAsset)
    if (outcome === 'conflict') { ElMessage.warning(`附件已存在且内容不同：${path}；未覆盖本地文件`); return }
    const existing = assets.value.find(item => item.path === path)
    if (existing) unifiedRepository.update<Asset>('asset', existing.calmyId, { mimeType: openAsset.mimeType, sizeBytes: data.byteLength, hash: hashOpenBytes(data), lifecycle: 'active', version: outcome === 'unchanged' ? existing.version : existing.version + 1 }, { expectedRevision: existing.revision })
    else unifiedRepository.createAsset({ path, mimeType: openAsset.mimeType, sizeBytes: data.byteLength, hash: hashOpenBytes(data), lifecycle: 'active', version: 1 })
    tick.value++
    ElMessage.success(outcome === 'unchanged' ? '附件已存在，元数据已校准' : '附件已保存并建立 Asset 记录')
  } catch (error) { ElMessage.error(error instanceof Error ? error.message : '附件导入失败') }
  finally { input.value = '' }
}
function downloadAsset(item: Asset): void {
  const openAsset = assetRepository.list().find(asset => asset.path === item.path)
  if (!openAsset) { ElMessage.warning('本地二进制不存在，只保留了 Asset 元数据'); return }
  const url = URL.createObjectURL(new Blob([openAsset.data], { type: openAsset.mimeType })); const anchor = document.createElement('a'); anchor.href = url; anchor.download = item.path.split('/').pop() || 'asset'; anchor.click(); URL.revokeObjectURL(url)
}
function previewAsset(item: Asset): void {
  const openAsset = assetRepository.list().find(asset => asset.path === item.path)
  if (!openAsset) { ElMessage.warning('本地二进制不存在，无法预览'); return }
  const url = URL.createObjectURL(new Blob([openAsset.data], { type: openAsset.mimeType })); window.open(url, '_blank', 'noopener,noreferrer'); window.setTimeout(() => URL.revokeObjectURL(url), 30000)
}
</script>

<template>
  <div class="library-page"><header class="page-head"><div><p class="eyebrow">LIBRARY · EARTH</p><h1 class="font-title">把留下来的东西安放好</h1><p>资源、洞察和 Seed 都保留来源，不再漂浮在工具模块里。</p></div><span class="count-pill">{{ resources.length + insights.length + seeds.length }} 项开放资产</span></header>
    <section class="create-panel beryl-card"><div class="panel-head"><div><p class="eyebrow">CAPTURE ASSET</p><h2 class="font-title">保存一个可复用的东西</h2></div><span>Resource 和 Seed 可以从记录、行动或复盘继续生长</span></div><div class="create-grid"><select v-model="kind"><option value="resource">Resource 资源</option><option value="seed">Seed 种子</option></select><el-input v-model="title" placeholder="标题" /><el-input v-model="body" placeholder="内容、做法或下一步" @keyup.enter="addItem" /><el-input v-if="kind === 'resource'" v-model="resourceUri" placeholder="外部 URI（可选）" /><input v-if="kind === 'resource'" v-model="resourceExpiresAt" type="date" title="过期日期（可选）"><select v-if="kind === 'resource'" v-model="resourceAssetIds" multiple><option v-for="asset in assets" :key="asset.calmyId" :value="asset.calmyId">绑定：{{ asset.path }}</option></select><button @click="addItem">保存</button></div></section>
    <section class="asset-panel beryl-card"><div class="panel-head"><div><p class="eyebrow">ASSET LIFECYCLE</p><h2 class="font-title">附件元数据</h2></div><span>{{ assets.length }} 个 Asset</span></div><div class="asset-form"><input type="file" @change="importBinaryAsset" title="选择真实附件"><input v-model="assetPath" placeholder="路径，例如：assets/manual.pdf"><input v-model="assetMimeType" placeholder="MIME，例如：application/pdf"><input v-model="assetSize" type="number" min="0" placeholder="大小（bytes）"><input v-model="assetHash" placeholder="hash"><input v-model="assetVersion" type="number" min="1" placeholder="版本"><input v-model="assetExternalUri" placeholder="外部 URI（可选）"><button @click="addAsset">保存 Asset</button></div><div class="asset-list"><article v-for="item in assets" :key="item.calmyId" class="asset-row"><div><b>{{ item.path }}</b><small>{{ item.mimeType }} · {{ item.sizeBytes }} bytes · v{{ item.version }} · {{ assetLifecycleLabel(item.lifecycle) }}</small></div><input :value="item.lifecycle" @change="updateAssetLifecycle(item, assetLifecycleValue($event))" list="asset-lifecycle-options"><button @click="previewAsset(item)">预览</button><button @click="downloadAsset(item)">下载</button><datalist id="asset-lifecycle-options"><option value="active">存在</option><option value="expired">过期</option><option value="retired">退休</option><option value="missing">缺失</option></datalist></article><p v-if="!assets.length" class="empty-copy">还没有附件元数据。</p></div></section><div class="library-grid"><section><div class="list-head"><div><p class="eyebrow">RESOURCES</p><h2 class="font-title">资源</h2></div><span>{{ resources.length }}</span></div><article v-for="item in resources" :key="item.calmyId" class="library-card beryl-card"><b>{{ item.title }}</b><p>{{ item.body || '暂无描述' }}</p><small class="asset-health">{{ resourceAssetState(item) }}</small><select :value="item.assetIds" multiple @change="updateResourceAssets(item, $event)"><option v-for="asset in assets" :key="asset.calmyId" :value="asset.calmyId">{{ asset.path }} · {{ assetLifecycleLabel(asset.lifecycle) }}</option></select><small>{{ item.kind }} · {{ resourceStatusLabel(item.status) }} · rev {{ item.revision }}<span v-if="item.expiresAt"> · 到期 {{ new Date(item.expiresAt).toLocaleDateString() }}</span></small><div class="card-actions"><button v-if="item.status === 'active'" @click="updateResourceStatus(item, 'expired')">标记过期</button><button v-if="item.status !== 'retired'" @click="updateResourceStatus(item, 'retired')">退休</button><button v-if="item.status === 'expired'" @click="updateResourceStatus(item, 'active')">恢复有效</button></div></article><p v-if="!resources.length" class="empty-copy">还没有资源。</p></section><section><div class="list-head"><div><p class="eyebrow">INSIGHTS & SEEDS</p><h2 class="font-title">洞察与种子</h2></div><span>{{ insights.length + seeds.length }}</span></div><article v-for="item in [...insights, ...seeds]" :key="item.calmyId" class="library-card beryl-card"><b>{{ item.title }}</b><p>{{ item.body }}</p><small>{{ item.entityType === 'insight' ? 'Insight' : 'Seed' }} · rev {{ item.revision }}</small><button v-if="item.entityType === 'seed'" @click="retireSeed(item)">退休</button></article><p v-if="!insights.length && !seeds.length" class="empty-copy">复盘后留下的洞察和 Seed 会出现在这里。</p></section></div>
  </div>
</template>

<style scoped>
.library-page{max-width:980px;margin:0 auto}.page-head{display:flex;align-items:end;justify-content:space-between;margin:6px 0 28px}.eyebrow{font-size:10px;letter-spacing:.13em;color:var(--scene);font-weight:700;margin:0 0 8px}.page-head h1{font-size:clamp(34px,4vw,48px);line-height:1;margin:0;letter-spacing:-.035em}.page-head p:last-child{margin:11px 0 0;font-size:13px;color:var(--c-text-2)}.count-pill{font-size:11px;padding:8px 12px;border-radius:99px;background:var(--scene-soft);color:var(--scene)}.create-panel{padding:18px;margin-bottom:30px}.panel-head,.list-head{display:flex;align-items:start;justify-content:space-between;gap:12px}.panel-head h2,.list-head h2{font-size:23px;margin:0}.panel-head>span,.list-head>span{font-size:10px;color:var(--c-text-3)}.create-grid{display:grid;grid-template-columns:150px 1fr 1.5fr auto;gap:8px;margin-top:16px}.create-grid select,.create-grid button,.library-card button{border:1px solid var(--c-border);background:var(--c-card);border-radius:8px;padding:7px 11px;color:var(--c-text);cursor:pointer;font-size:12px}.create-grid select{min-width:0}.create-grid button:hover,.library-card button:hover{border-color:var(--scene);color:var(--scene)}.asset-panel{padding:18px;margin-bottom:22px}.asset-form{display:grid;grid-template-columns:1.5fr 1.2fr .8fr 1.2fr .7fr 1.5fr auto;gap:8px;margin-top:14px}.asset-form input,.asset-form button,.asset-row input,.asset-row button{min-width:0;border:1px solid var(--c-border);border-radius:8px;background:var(--c-bg);color:var(--c-text);padding:7px 9px;font:inherit;font-size:11px}.asset-form button,.asset-row button{cursor:pointer;background:var(--scene-soft);color:var(--scene)}.asset-list{display:grid;gap:7px;margin-top:14px}.asset-row{display:grid;grid-template-columns:1fr 100px auto auto;gap:10px;align-items:center;border-top:1px solid var(--c-border-soft);padding-top:9px}.asset-row div{display:grid;gap:4px;min-width:0}.asset-row b{font-size:11px;overflow-wrap:anywhere}.asset-row small{font-size:10px;color:var(--c-text-3)}.card-actions{display:flex;gap:5px;justify-content:flex-end;margin-top:9px}.card-actions button{position:static}.library-card select{width:100%;margin-top:8px;min-height:34px;border:1px solid var(--c-border);border-radius:8px;background:var(--c-bg);color:var(--c-text);padding:6px 8px;font:inherit;font-size:10px}.asset-health{display:block;color:var(--scene);margin-top:5px}.library-grid{display:grid;grid-template-columns:1fr 1fr;gap:22px}.list-head{align-items:end;margin-bottom:12px}.library-card{position:relative;padding:15px;margin-bottom:9px}.library-card b{font-size:14px}.library-card p{font-size:12px;line-height:1.6;color:var(--c-text-2);margin:9px 0 12px;white-space:pre-wrap}.library-card small{font-size:10px;color:var(--c-text-3)}.library-card button{position:absolute;right:12px;bottom:12px;font-size:10px;background:transparent;color:var(--c-text-3)}.empty-copy{font-size:12px;color:var(--c-text-3);padding:22px 4px}@media(max-width:860px){.asset-form{grid-template-columns:1fr 1fr 1fr}.asset-form button{grid-column:1/-1}}@media(max-width:680px){.page-head{display:block}.count-pill{display:inline-block;margin-top:14px}.create-grid,.library-grid{grid-template-columns:1fr}.create-grid select,.create-grid button{height:34px}}
</style>
